import{_ as t,o,c as r,a}from"./app.c1132791.js";const u=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[{"level":2,"title":"GitHub Pages","slug":"github-pages","link":"#github-pages","children":[]},{"level":2,"title":"Netlify","slug":"netlify","link":"#netlify","children":[]},{"level":2,"title":"Vercel","slug":"vercel","link":"#vercel","children":[]}],"relativePath":"getting-started/deploy.md"}'),i={name:"getting-started/deploy.md"};function n(s,e,l,p,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-hidden="true">#</a></h1><h2 id="github-pages" tabindex="-1">GitHub Pages <a class="header-anchor" href="#github-pages" aria-hidden="true">#</a></h2><p>This project comes with a GitHub Actions script that automatically generates a deployment file that runs after you commit your changes and then commits to the gh-pages branch.</p><p>To use it, just set the GitHub Pages deployment branch to gh-pages.</p><blockquote><p>If the GitHub Actions script does not run automatically after you commit your changes, check to see if there is another branch in your repository, or you can run the script manually.</p></blockquote><h2 id="netlify" tabindex="-1">Netlify <a class="header-anchor" href="#netlify" aria-hidden="true">#</a></h2><p>This project comes with <a href="https://github.com/importantimport/urara/blob/main/netlify.toml" target="_blank" rel="noreferrer"><strong>Build Profile</strong></a> for Netlify, so when importing the project, there is no need to fill in the build settings.</p><p>To deploy this project on Netlify, you need to have a Netlify account and install the <a href="https://github.com/apps/netlify/installations/new" target="_blank" rel="noreferrer"><strong>Netlify app</strong></a> in the desired repository to access the selected repository.</p><p>Next, just follow the <a href="https://app.netlify.com/start" target="_blank" rel="noreferrer"><strong>Import an existing project</strong></a> page to complete the deployment process.</p><h2 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-hidden="true">#</a></h2><p>To deploy this project on Vercel, you need to have a Vercel account to start <a href="https://vercel.com/new" target="_blank" rel="noreferrer"><strong>Add New Project</strong></a>.</p><p>You can import projects from a public git repository, or to import a private GitHub repository, you need to associate a GitHub account for authorization.</p><p>Once you select a repository, Vercel automatically recognizes the repository and selects the appropriate schema without having to fill in the build and output settings.</p><p>You can also add additional settings as needed, then deploy, and wait for the deployment to complete.</p>',14)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
